const vLab = new MathTex({ latex: 'x=3', color: RED });
await vLab.waitForRender();
vLab.scale(0.7);
vLab.moveTo([ax.c2p(3, 11)[0] + 0.55, ax.c2p(3, 11)[1], 0]);

const hLab = new MathTex({ latex: 'y=2', color: GREEN });
